// POST do agente/Salesbot quando form Flow concluído.
// Webhook IN: https://n8n-new-n8n.ca31ey.easypanel.host/webhook/kommo-form-sum-completed

const body = $json.body ?? $json;

function pick(obj, keys) {
  for (const k of keys) {
    const v = obj?.[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return null;
}

function normalizePhone(v) {
  if (!v) return null;
  let d = String(v).replace(/\D/g, '');
  if (!d) return null;
  if (!d.startsWith('55') && (d.length === 10 || d.length === 11)) d = `55${d}`;
  return `${d}@s.whatsapp.net`;
}

const leadId = Number(pick(body, ['lead_id', 'leadId', 'id_lead', 'entity_id']));
const phoneRaw = pick(body, ['phone', 'telefone', 'wa_id', 'whatsapp', 'contact_phone']);
const message = pick(body, ['message', 'text', 'body']) || '';
const source = pick(body, ['source']) || 'kommo_salesbot';

const isFlowSignal =
  /respostas\s+recebidas\s+(no\s+)?flow/i.test(message) ||
  /flow\s+responses\s+received/i.test(message) ||
  body.trigger === 'form_flow_completed' ||
  body.form_completed === true;

if (!Number.isFinite(leadId) || leadId <= 0) {
  return [{ json: { ok: false, error: 'lead_id ausente ou inválido', raw: body } }];
}

return [{
  json: {
    ok: true,
    lead_id: leadId,
    phone_raw: phoneRaw,
    session_id: normalizePhone(phoneRaw),
    message,
    source,
    is_flow_signal: isFlowSignal,
    bridge_id: `kommo-bridge-${leadId}-${Date.now()}`,
  },
}];

const bridge = $('Normalizar payload Kommo').item.json;
const lead = $('GET lead Kommo').item.json;
const notesPayload = $('GET notas lead').item.json;
const notes = notesPayload?._embedded?.notes || [];

function pickCf(fields, id) {
  const f = (fields || []).find((x) => Number(x.field_id) === Number(id));
  if (!f?.values?.length) return null;
  const v = f.values[0];
  return v?.value != null ? String(v.value).trim() : null;
}

function formatDateToDDMMYYYY(v) {
  const s = String(v ?? '').trim();
  if (!s) return null;
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(s)) return s;
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (iso) return `${iso[3]}/${iso[2]}/${iso[1]}`;
  const digits = s.replace(/\D/g, '');
  if (digits.length === 8) return `${digits.slice(0, 2)}/${digits.slice(2, 4)}/${digits.slice(4, 8)}`;
  return s;
}

function mapSexo(enumId) {
  const mapa = { '1194759': 'Masculino' };
  return mapa[String(enumId)] ?? null;
}

function normalizeBrazilPhone(v) {
  let digits = String(v ?? '').replace(/\D/g, '');
  if (!digits) return null;
  if (!digits.startsWith('55') && (digits.length === 10 || digits.length === 11)) digits = `55${digits}`;
  return digits;
}

function extractResponseJsonFromNotes(noteList) {
  for (const n of noteList) {
    const blob = JSON.stringify(n.params || n);
    const m2 = blob.match(/"response_json"\s*:\s*"(\{.*?\})"/);
    if (m2) {
      try {
        return JSON.parse(m2[1].replace(/\\"/g, '"'));
      } catch {}
    }
    if (/TextInput_1475361_2/.test(blob)) {
      try {
        const raw = blob.match(/\{[^{}]*TextInput_1475361_2[^{}]*\}/);
        if (raw) return JSON.parse(raw[0]);
      } catch {}
    }
  }
  return null;
}

const cfs = lead.custom_fields_values || [];
const data = extractResponseJsonFromNotes(notes);

const parsedFromFlow = data
  ? {
      nome_completo: data.TextInput_1475361_2 || null,
      cpf: data.TextInput_1475363_2 || null,
      telefone: data.TextInput_1475397_2 || null,
      email: data.TextInput_1475395_2 || null,
      sexo_enum_id: data.Dropdown_1475971_2 || null,
      data_nascimento: formatDateToDDMMYYYY(data.TextInput_1475467_2),
      source: 'notes_response_json',
    }
  : null;

const fromCard = {
  nome_completo: pickCf(cfs, 1475361),
  cpf: pickCf(cfs, 1475363),
  telefone: pickCf(cfs, 1475397),
  email: pickCf(cfs, 1475395),
  data_nascimento: formatDateToDDMMYYYY(pickCf(cfs, 1475467)),
  sexo: pickCf(cfs, 1475971),
  source: 'kommo_card_fields',
};

const contact = lead._embedded?.contacts?.[0];
const phoneFromContact = contact?.custom_fields_values
  ? contact.custom_fields_values.find((f) => /phone|telefone/i.test(String(f.field_code || f.field_name || '')))
  : null;
const phoneContactVal = phoneFromContact?.values?.[0]?.value || null;

const telefoneNorm = normalizeBrazilPhone(
  parsedFromFlow?.telefone || fromCard.telefone || phoneContactVal || bridge.phone_raw,
);

const sessionId =
  bridge.session_id || (telefoneNorm ? `${telefoneNorm}@s.whatsapp.net` : null);

return [{
  json: {
    ok: true,
    lead_id: bridge.lead_id,
    bridge_id: bridge.bridge_id,
    session_id: sessionId,
    nome_completo: parsedFromFlow?.nome_completo || fromCard.nome_completo || null,
    cpf: parsedFromFlow?.cpf || fromCard.cpf || null,
    telefone_normalizado: telefoneNorm,
    email: parsedFromFlow?.email || fromCard.email || null,
    sexo: parsedFromFlow?.sexo_enum_id ? mapSexo(parsedFromFlow.sexo_enum_id) : fromCard.sexo,
    data_nascimento: parsedFromFlow?.data_nascimento || fromCard.data_nascimento || null,
    data_source: parsedFromFlow ? parsedFromFlow.source : fromCard.source,
    has_form_fields: Boolean(
      (parsedFromFlow?.nome_completo || fromCard.nome_completo) &&
        (parsedFromFlow?.cpf || fromCard.cpf),
    ),
    is_flow_signal: bridge.is_flow_signal,
  },
}];

